const num1Input = document.getElementById('num1');
const num2Input = document.getElementById('num2');
const resultDiv = document.getElementById('result');

document.querySelector('.buttons').addEventListener('click', function(event) {
  const button = event.target.closest('button[data-op]');
  if (!button) return;
  calculate(button.dataset.op);
});

document.getElementById('clear').addEventListener('click', function() {
  num1Input.value = '';
  num2Input.value = '';
  resultDiv.textContent = 'Tulemus kuvatakse siin';
  resultDiv.className = 'result';
});

function calculate(operator) {
  const a = parseFloat(num1Input.value);
  const b = parseFloat(num2Input.value);

  if (isNaN(a) || isNaN(b)) {
    showError('Palun sisesta mõlemasse välja arv');
    return;
  }

  if (operator === '/' && b === 0) {
    showError('Nulliga jagamine pole lubatud');
    return;
  }

  const operations = {
    '+': a + b,
    '-': a - b,
    '*': a * b,
    '/': a / b,
  };

  const result = operations[operator];
  resultDiv.textContent = `${a} ${operator} ${b} = ${result}`;
  resultDiv.className = 'result success';
}

function showError(message) {
  resultDiv.textContent = message;
  resultDiv.className = 'result error';
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: sans-serif;
  background: #f0f0f0;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.calculator {
  background: white;
  border-radius: 12px;
  padding: 24px;
  box-shadow: 0 4px 20px rgba(0,0,0,0.1);
  width: 300px;
}

h1 { text-align: center; margin-bottom: 16px; font-size: 20px; }

.inputs { display: flex; flex-direction: column; gap: 8px; margin-bottom: 12px; }

input[type="number"] {
  padding: 10px;
  border: 1px solid #ccc;
  border-radius: 6px;
  font-size: 16px;
  width: 100%;
}

.buttons {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-bottom: 12px;
}

button {
  padding: 12px;
  border: none;
  border-radius: 6px;
  background: #4a90e2;
  color: white;
  font-size: 18px;
  cursor: pointer;
}

button:hover { background: #357abd; }

#clear { width: 100%; background: #ccc; color: #333; margin-top: 8px; }
#clear:hover { background: #bbb; }

.result {
  padding: 12px;
  text-align: center;
  background: #f8f8f8;
  border-radius: 6px;
  border: 1px solid #e0e0e0;
  min-height: 44px;
}

.result.success { border-color: #4dd089; background: #f0fff8; color: #1a7a45; }
.result.error { border-color: #ef5d5d; background: #fff0f0; color: #b00020; }
